/** Hook box wraps at this fraction of the output width. */
export const HOOK_BOX_WIDTH_FRAC = 0.9
/** Font size as a fraction of that box width. */
export const HOOK_FONT_WIDTH_FRAC = 0.046
/** Line box height, as a multiple of font size. */
export const HOOK_LINE_HEIGHT = 1.25

export interface HookStyleOption {
  id: string
  label: string
  /** Stroke/glow bleed baked into the box size by the renderer, in export px. */
  innerPad: number
  boxCss: CSSProperties
  textCss: CSSProperties
  /** Renderer applies a seeded slice/noise distort — preview approximates it. */
  glitch?: boolean
  /** Per-style font size multiplier, applied on top of the user's font_scale. */
  sizeMult?: number
}

